/**
 * This script provides an object class (SlaveDemographics) with a slave's demographics (sex, nationality, and "race"),
 * and a function (generateSlaveDemographics) to generate an instance of this class randomly. Height.randomAdult uses sex,
 * nationality, and race are used to generate a slave's adult height. Normally, these values are randomly generated by
 * generateNewSlave, which then generates heights based on them, and, finally, uses height to generate the slave's
 * shoulders and hips. This sequencing becomes a problem when it's necessary to generate a height outside generateNewSlave,
 * e.g., when the Recruiter is ordered to recruit slaves who are taller or shorter than average: lacking sex, nationality,
 * and race, it's impossible to generate height accurately, but altering height after a slave has been generated results
 * in shoulders and hips that tend not to match a slave's height. Using generateSlaveDemographics allows breaks up this
 * sequence, allowing the demographics to be generated without fully generating a slave.
 *
 * Note that the constructor for this class uses the argument "sex", following the format of GenerateNewSlave, but name of
 * the attribute in question is "genes", following the pattern of class SlaveState.
 */

/**
 * This object class holds a slave's sex, nationality, and race, and can be used to generate adult height without
 * fully generating a slave.
 * @see globalThis.generateSlaveDemographics
 * @see globalThis.generateNewSlave
 */
App.Entity.SlaveDemographics = class SlaveDemographics {
	constructor(seed=undefined) {
		/** @type {string} the seed that was passed or a new seed from generateNewID() is none was passed  */
		this.seed = seed ? String(seed) : generateNewID();
		/** @type {FC.GenderGenes} Their sex */
		this.genes = "XX";
		/** @type {string} Their nationality */
		this.nationality = "slave";
		/** @type {FC.Race} Their race */
		this.race = "white";
	}
};
